foreach ($products as $name => $specs) {
    $stmt = $conn->prepare("UPDATE products SET specifications = ? WHERE name LIKE ?");
    $search_name = '%' . $name . '%';
    $stmt->bind_param("ss", $specs, $search_name);
    if ($stmt->execute()) {
        echo "Updated specifications for: $name\n";
    } else {
        echo "Error updating $name: " . $stmt->error . "\n";
    }
}

